"// hooks/retention.ts",
"var DAY3 = 24 * 60 * 60 * 1000;",
"var KB = 1024;",
"var MB = 1024 * KB;",
"var RETENTION = {",
"  endedAgentMs: 3 * DAY3,",
"  agentMs: 30 * DAY3,",
"  endedMirrorMs: 7 * DAY3,",
"  openMirrorMs: 30 * DAY3,",
"  recordMs: 30 * DAY3,",
"  pendingQuestionMs: 3 * DAY3,",
"  storeTempMs: DAY3,",
"  failedInboxMs: 7 * DAY3,",
"  monthPartBytes: MB,",
"  progressSoftBytes: 512 * KB,",
"  storeWarnBytes: 1.2 * MB,",
"  storeCapBytes: 1.5 * MB,",
"  capRetryMs: 6 * 60 * 60 * 1000,",
"  prunedDays: 7,",
"  pruneReads: 20,",
"  pruneStartReads: 10",
"};",
"var monthPart = (base, part) => part <= 1 ? base : base.replace(/(\\.md)?$/i, `-${part}$1`);",
"var currentPart = (base, sizeOf, limit = RETENTION.monthPartBytes) => {",
"  for (let part = 1;; part += 1) {",
"    const path = monthPart(base, part);",
"    const size = sizeOf(path);",
"    if (size === null || size < limit)",
"      return path;",
"  }",
"};",
"var monthParts = (base, isThere) => {",
"  const parts = [];",
"  for (let part = 1;isThere(monthPart(base, part)); part += 1)",
"    parts.push(monthPart(base, part));",
"  return parts;",
"};",
"var sizeWarnings = (sizes, s = ZH_TW) => sizes.progress > RETENTION.progressSoftBytes || sizes.store > RETENTION.storeWarnBytes ? [s.boardLarge] : [];",
"var sizeDetails = (sizes, s = ZH_TW) => [",
"  ...sizes.progress > RETENTION.progressSoftBytes ? [s.progressLarge(Math.round(sizes.progress / KB), RETENTION.progressSoftBytes / KB)] : [],",
"  ...sizes.store > RETENTION.storeWarnBytes ? [s.storeLarge((sizes.store / MB).toFixed(1), (RETENTION.storeCapBytes / MB).toFixed(1))] : []",
"];",
"var storageDetails = (sizes, finished, s = ZH_TW) => {",
"  const details = [...sizeDetails(sizes, s), ...finished > 0 ? [s.canArchive(finished)] : []];",
"  return details.length === 0 ? undefined : details.join(\" · \");",
"};",
