"};",
"var divisorOf = (degree) => {",
"  const result = Array.from({ length: degree }, (_, i) => i === degree - 1 ? 1 : 0);",
"  let root = 1;",
"  for (let i = 0;i < degree; i += 1) {",
"    for (let j = 0;j < degree; j += 1) {",
"      result[j] = mul(result[j] ?? 0, root);",
"      if (j + 1 < degree)",
"        result[j] = (result[j] ?? 0) ^ (result[j + 1] ?? 0);",
"    }",
"    root = mul(root, 2);",
"  }",
"  return result;",
"};",
"var remainderOf = (data, divisor) => {",
"  const result = divisor.map(() => 0);",
"  for (const byte of data) {",
"    const factor = byte ^ (result.shift() ?? 0);",
"    result.push(0);",
"    divisor.forEach((coefficient, i) => {",
