"  return result;",
"};",
"var dataCodewords = (version) => Math.floor(rawModules(version) / 8) - (ECC_PER_BLOCK[version] ?? 0) * (BLOCKS[version] ?? 0);",
"var alignmentOf = (version) => {",
"  if (version === 1)",
