"  return result;",
"};",
"var isMasked = (mask, x, y) => [",
"  (x + y) % 2 === 0,",
"  y % 2 === 0,",
"  x % 3 === 0,",
"  (x + y) % 3 === 0,",
"  (Math.floor(x / 3) + Math.floor(y / 2)) % 2 === 0,",
"  x * y % 2 + x * y % 3 === 0,",
"  (x * y % 2 + x * y % 3) % 2 === 0,",
"  ((x + y) % 2 + x * y % 3) % 2 === 0",
"][mask] === true;",
"var penaltyOf = (grid) => {",
"  const size = grid.length;",
"  const at = (x, y) => grid[y]?.[x] === true;",
"  let result = 0;",
"  const lines = [",
"    ...grid.map((_, y) => grid.map((_, x) => at(x, y))),",
"    ...grid.map((_, x) => grid.map((_, y) => at(x, y)))",
"  ];",
"  const finder = [true, false, true, true, true, false, true];",
"  for (const line of lines) {",
"    let run = 1;",
"    for (let i = 1;i <= size; i += 1) {",
"      if (i < size && line[i] === line[i - 1]) {",
"        run += 1;",
"        continue;",
"      }",
"      if (run >= 5)",
"        result += run - 2;",
"      run = 1;",
"    }",
"    for (let i = 0;i + 7 <= size; i += 1) {",
"      if (!finder.every((isDark, j) => line[i + j] === isDark))",
"        continue;",
"      const before = Array.from({ length: 4 }, (_, j) => line[i - 1 - j] ?? false);",
"      const after = Array.from({ length: 4 }, (_, j) => line[i + 7 + j] ?? false);",
"      if (before.every((isDark) => !isDark) || after.every((isDark) => !isDark))",
"        result += 40;",
"    }",
"  }",
"  for (let y = 0;y + 1 < size; y += 1) {",
"    for (let x = 0;x + 1 < size; x += 1) {",
"      const isDark = at(x, y);",
"      if (at(x + 1, y) === isDark && at(x, y + 1) === isDark && at(x + 1, y + 1) === isDark)",
"        result += 3;",
"    }",
"  }",
"  const darkCount = grid.reduce((sum, row) => sum + row.filter(Boolean).length, 0);",
"  const total = size * size;",
